p='BulkMoveService.java'; s=open(p).read()
old='''        List<Long> ordered = new ArrayList<>();
        List<Claim> sheetClaims = claims.list(sheetId);
        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
            for (Claim claim : sheetClaims) {
                if (claim.getPersonId().equals(person.getId()) && selected.contains(claim.getId())) {
                    ordered.add(claim.getId());
                }
            }
        }
'''
new='''        List<Long> ordered = new ArrayList<>();
        List<Claim> sheetClaims = claims.list(sheetId);
        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
            sheetClaims.stream()
                    .filter(claim -> claim.getPersonId().equals(person.getId()) && selected.contains(claim.getId()))
                    .sorted(NEWEST_FIRST)
                    .forEach(claim -> ordered.add(claim.getId()));
        }
